from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    # cache: key -> [value, write_time]
    cache = OrderedDict()
    results = []

    def is_expired(key, t):
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]

            # check if key exists but expired -> remove it (treat as absent)
            if key in cache and is_expired(key, t):
                del cache[key]

            if key in cache:
                # update existing entry, move to end
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                # new key (either truly new or was expired and removed)
                if len(cache) >= capacity:
                    # evict LRU
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)

        elif kind == 'get':
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

